<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';
$user=Auth::requireLogin();$type=$_GET['type']??'umrah';$umrah=$type==='umrah';Auth::requirePermission($umrah?'umrah.manage':'services.manage');$pdo=Database::connection();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();try{$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$slug=strtolower(trim($_POST['slug']??''));if(mb_strlen($title)<3||!preg_match('/^[a-z0-9-]{2,190}$/',$slug))throw new RuntimeException('الاسم والمعرّف مطلوبان.');$status=$umrah?(in_array($_POST['status']??'active',['active','hidden','full'],true)?$_POST['status']:'active'):(in_array($_POST['status']??'active',['active','hidden'],true)?$_POST['status']:'active');
if($umrah){$data=[$title,$slug,trim($_POST['description']??''),(int)($_POST['duration_days']??0)?:null,$_POST['departure_at']?:null,($_POST['price']??'')!==''?(float)$_POST['price']:null,$_POST['currency']??'SAR',(int)($_POST['seats_total']??0)?:null,trim($_POST['included_services']??''),$status];if($id){$data[]=$id;$pdo->prepare('UPDATE umrah_programs SET title=?,slug=?,description=?,duration_days=?,departure_at=?,price=?,currency=?,seats_total=?,included_services=?,status=? WHERE id=?')->execute($data);}else $pdo->prepare('INSERT INTO umrah_programs(title,slug,description,duration_days,departure_at,price,currency,seats_total,included_services,status) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute($data);}
else{$stype=in_array($_POST['service_type']??'visa',['visa','visit','other'],true)?$_POST['service_type']:'visa';$data=[$title,$slug,$stype,trim($_POST['description']??''),trim($_POST['requirements']??''),($_POST['price']??'')!==''?(float)$_POST['price']:null,$_POST['currency']??'SAR',trim($_POST['processing_days']??''),$status];if($id){$data[]=$id;$pdo->prepare('UPDATE services SET title=?,slug=?,service_type=?,description=?,requirements=?,price=?,currency=?,processing_days=?,status=? WHERE id=?')->execute($data);}else $pdo->prepare('INSERT INTO services(title,slug,service_type,description,requirements,price,currency,processing_days,status) VALUES(?,?,?,?,?,?,?,?,?)')->execute($data);}
admin_log($pdo,$user,$id?'catalog.updated':'catalog.created',$umrah?'umrah_program':'service',$id?: (int)$pdo->lastInsertId(),'حفظ بيانات '.($umrah?'برنامج عمرة':'خدمة'));redirect('/admin/catalog.php?type='.($umrah?'umrah':'service').'&saved=1');
}catch(Throwable $e){$error=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM '.($umrah?'umrah_programs':'services').' WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}
$rows=$pdo->query('SELECT * FROM '.($umrah?'umrah_programs':'services').' ORDER BY id DESC LIMIT 300')->fetchAll();
admin_page_start($umrah?'إدارة برامج العمرة':'إدارة التأشيرات والزيارات',$user);
echo '<p><a class="admin-link" href="/admin/catalog.php?type='.($umrah?'service':'umrah').'">التبديل إلى '.($umrah?'الخدمات':'برامج العمرة').'</a></p>';
if($error)echo '<p class="notice danger">'.e($error).'</p>';if(isset($_GET['saved']))echo '<p class="notice">تم حفظ البيانات.</p>';
$v=fn($k,$d='')=>e($edit[$k]??$d);
echo '<section class="panel"><h2>'.($edit?'تعديل':'إضافة').' '.($umrah?'برنامج عمرة':'خدمة').'</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(Security::csrf()).'"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><label>الاسم<input name="title" required value="'.$v('title').'"></label><label>المعرّف اللاتيني<input name="slug" required pattern="[a-z0-9-]{2,190}" value="'.$v('slug').'"></label>';
if($umrah)echo '<label>المدة بالأيام<input type="number" min="1" name="duration_days" value="'.$v('duration_days').'"></label><label>موعد الانطلاق<input type="datetime-local" name="departure_at" value="'.($edit&&!empty($edit['departure_at'])?e(date('Y-m-d\TH:i',strtotime($edit['departure_at']))):'').'"></label><label>عدد المقاعد<input type="number" min="0" name="seats_total" value="'.$v('seats_total').'"></label><label class="wide">الخدمات المشمولة<textarea name="included_services">'.$v('included_services').'</textarea></label>';
else echo '<label>نوع الخدمة<select name="service_type"><option value="visa">تأشيرة</option><option value="visit">زيارة</option><option value="other">أخرى</option></select></label><label>مدة الإنجاز<input name="processing_days" value="'.$v('processing_days').'"></label><label class="wide">المتطلبات<textarea name="requirements">'.$v('requirements').'</textarea></label>';
echo '<label>السعر<input type="number" step=".01" min="0" name="price" value="'.$v('price').'"></label><label>العملة<select name="currency"><option value="SAR">ريال سعودي</option><option value="YER">ريال يمني</option></select></label><label>الحالة<select name="status">';
foreach(($umrah?['active'=>'منشور','hidden'=>'مخفي','full'=>'مكتمل']:['active'=>'منشور','hidden'=>'مخفي']) as $k=>$label)echo '<option value="'.$k.'" '.(($edit['status']??'active')===$k?'selected':'').'>'.$label.'</option>';
echo '</select></label><label class="wide">الوصف<textarea name="description">'.$v('description').'</textarea></label><button class="btn btn-primary" type="submit">حفظ</button>'.($edit?'<a class="admin-link" href="/admin/catalog.php?type='.($umrah?'umrah':'service').'">إلغاء التعديل</a>':'').'</form></section><section class="panel"><h2>السجلات</h2><table><thead><tr><th>الاسم</th><th>النوع</th><th>السعر</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>';
foreach($rows as $r)echo '<tr><td>'.e($r['title']).'</td><td>'.($umrah?'عمرة':e($r['service_type'])).'</td><td>'.e($r['price']===null?'عند الطلب':$r['price'].' '.$r['currency']).'</td><td>'.e($r['status']).'</td><td><a class="admin-link" href="/admin/catalog.php?type='.($umrah?'umrah':'service').'&edit='.(int)$r['id'].'">تعديل</a></td></tr>';
if(!$rows)echo '<tr><td colspan="5">لا توجد سجلات.</td></tr>';echo '</tbody></table></section>';admin_page_end();
